from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = dict(jumps)
    resolved = list(range(n + 1))

    for start in range(n + 1):
        cell = start
        while cell in jump:
            cell = jump[cell]
        resolved[start] = cell

    transitions = {}
    reverse = [[] for _ in range(n + 1)]
    reachable = [0]
    seen = {0}

    for cell in reachable:
        if cell == n:
            continue

        counts = {}
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            landing = resolved[landing]
            counts[landing] = counts.get(landing, 0) + 1

        transitions[cell] = counts
        for landing in counts:
            reverse[landing].append(cell)
            if landing not in seen:
                seen.add(landing)
                reachable.append(landing)

    # Every reachable state must have a path to the terminal state.
    can_finish = {n}
    stack = [n]
    while stack:
        cell = stack.pop()
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                stack.append(previous)

    if any(cell not in can_finish for cell in reachable):
        return None

    states = [cell for cell in reachable if cell != n]
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]

    # m * E[cell] - sum(count * E[next_cell]) = m.
    for cell in states:
        i = index[cell]
        matrix[i][i] = m
        matrix[i][size] = m
        for landing, count in transitions[cell].items():
            if landing != n:
                matrix[i][index[landing]] -= count

    # Fraction-free Bareiss elimination. Transience guarantees nonzero pivots.
    previous_pivot = 1
    for k in range(size - 1):
        pivot = matrix[k][k]
        pivot_row = matrix[k]

        for i in range(k + 1, size):
            row = matrix[i]
            factor = row[k]
            for j in range(k + 1, size + 1):
                row[j] = (
                    row[j] * pivot - factor * pivot_row[j]
                ) // previous_pivot
            row[k] = 0

        previous_pivot = pivot

    expectation = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            if matrix[i][j]:
                value -= matrix[i][j] * expectation[j]
        expectation[i] = value / matrix[i][i]

    answer = expectation[index[0]]
    return [answer.numerator, answer.denominator]
